// generated by tcacomp — deterministic output; do not edit
#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T SoftmaxCombine0(T p0, T p1) {
  return (p0 + p1);
}

// Softmax: launch 16 CTAs x 64 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 8 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(64) Softmax(uint32_t R, uint32_t e8, uint32_t C, const float* __restrict__ x, const float* __restrict__ z, float* __restrict__ out) {
  tca::rt::TensorView<const float, 3u> x_v(x, R, 8u, C);
  tca::rt::TensorView<const float, 3u> z_v(z, R, 8u, C);
  tca::rt::TensorView<float, 2u> out_v(out, R, C);
  // dynamic SMEM pool (8 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];
  tca::rt::Frag<float, 2u, 1u, 32u> tca_f0;
  tca::rt::Frag<float, 2u, 1u, 32u> tca_f1;

  tca::rt::KernelInfo kinfo;
  // LNT #0: R=CTA(T=256,LoC=16) C=sequential(T=32,LoC=1) e8=thread/warp(T=32,LoC=2) dim=thread/warp(LoC=64) dim=sequential(LoC=1) e8=sequential(T=32,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 16u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 16u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 2u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 2u);
    auto c0 = 0.0f;
    auto c1 = 0u;
    auto v0 = R;
    auto c2 = 2u;
    auto v1 = C;
    auto c3 = 1u;
    auto v2 = 8u;
    auto v3 = grid_map0.index(0u);
    auto c4 = 256u;
    auto v4 = (v3 * c4);
    auto c5 = 32u;
    auto v5 = thread_map1.index(0u);
    auto v6 = (v5 * c5);
    auto v7 = thread_map1.lane_id();
    auto v8 = (v7 + c3);
    auto v9 = (v8 * c3);
    auto v10 = (v7 * c3);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, SoftmaxCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 2u));
    // @R tile-between rounds — CTA, T=256, LoC=16 (map dim 0)
    for (auto R_it0 = tca::rt::CtaIterator(grid_map0, 0u, 16u, 0u, 4096u, v0); R_it0.Has(); R_it0.Next()) {
      auto v11 = (v4 + R_it0.Index());
      auto v12 = tca::rt::umin(v11, v0);
      auto v13 = (v0 - v12);
      auto v14 = tca::rt::umin(c4, v13);
      // @C tile-between rounds — sequential, T=32, LoC=1
      for (auto C_it1 = tca::rt::SeqIterator(0u, 32u, v1); C_it1.Has(); C_it1.Next()) {
        auto v15 = tca::rt::umin(C_it1.Index(), v1);
        auto v16 = (v1 - v15);
        auto v17 = tca::rt::umin(c5, v16);
        // @R walk — sequential, LoC=1
        for (auto R_it2 = tca::rt::SeqIterator(0u, 1u, v14); R_it2.Has(); R_it2.Next()) {
          auto v18 = (v11 + R_it2.Index());
          // @C walk — sequential, LoC=1
          for (auto C_it3 = tca::rt::SeqIterator(0u, 1u, v17); C_it3.Has(); C_it3.Next()) {
            // per-element bracket opens (argument-free; re-initializes from the construction-time init)
            reducer0.Init();
            // @e8 tile-between rounds — thread/warp, T=32, LoC=2 (map dim 0)
            for (auto e8_it4 = tca::rt::ThrIterator(thread_map1, 0u, 2u, 0u, 64u, v2); e8_it4.Has(); e8_it4.Next()) {
              auto v19 = (v6 + e8_it4.Index());
              auto v20 = tca::rt::umin(v19, v2);
              auto v21 = (v2 - v20);
              auto v22 = tca::rt::umin(c5, v21);
              auto v23 = tca::rt::umin(v9, v22);
              auto v24 = (v19 + v10);
              // per-thread tile fill of x (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f0, tca::rt::TensorWindow(x_v, v18, v24, C_it1.Index()));
              // per-thread tile fill of z (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f1, tca::rt::TensorWindow(z_v, v18, v24, C_it1.Index()));
              // @e8 inside walk (tile elements) — T=32
              for (auto e8_it5 = tca::rt::SeqIterator((v7 * c3), 1u, v23); e8_it5.Has(); e8_it5.Next()) {
                auto v25 = (e8_it5.Index() - v10);
                auto v26 = tca_f0.Get(v25, C_it3.Index());
                auto v27 = expf(v26);
                auto v28 = tca_f1.Get(v25, C_it3.Index());
                auto v29 = (v27 * v28);
                reducer0.Reduce(v29);
              }
            }
            // per-element combine — every participant receives the element's final value
            auto v30 = reducer0.Combine();
            // single-owner store — the element's owner thread writes (R2/R3)
            if (thread_map1.is_first_in_cta()) {
              out_v.Set(v30, (v11 + R_it2.Index()), (C_it1.Index() + C_it3.Index()));
            }
          }
        }
      }
    }
  }
}

}  // namespace

void SoftmaxLaunch(uint32_t e8, const tca::Tensor<float, 3u>& x, const tca::Tensor<float, 3u>& z, tca::Tensor<float, 2u>& out, cudaStream_t tca_stream) {
  const uint32_t R = x.Dim(0u);
  const uint32_t C = x.Dim(2u);
  TCA_REQUIRE(z.Dim(0u) == R, "z.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(z.Dim(2u) == C, "z.Dim(2) must equal C (dim C)");
  TCA_REQUIRE(out.Dim(0u) == R, "out.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(out.Dim(1u) == C, "out.Dim(1) must equal C (dim C)");
  tca::rt::ValidateLaunch(dim3(16u, 1u, 1u), dim3(64u, 1u, 1u), 8u, 512u);
  Softmax<<<dim3(16u, 1u, 1u), dim3(64u, 1u, 1u), 8u, tca_stream>>>(R, e8, C, x.Data(), z.Data(), out.Data());
  TCA_CUDA_CHECK(cudaGetLastError());
}
